function hexToRgb(hex) {
  const h = hex.replace("#", "");
  return { r: parseInt(h.slice(0, 2), 16), g: parseInt(h.slice(2, 4), 16), b: parseInt(h.slice(4, 6), 16) };
}
function rgbToHsl({ r, g, b }) {
  r /= 255; g /= 255; b /= 255;
  const max = Math.max(r, g, b), min = Math.min(r, g, b);
  let h = 0, s = 0; const l = (max + min) / 2;
  if (max !== min) {
    const d = max - min;
    s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
    switch (max) {
      case r: h = (g - b) / d + (g < b ? 6 : 0); break;
      case g: h = (b - r) / d + 2; break;
      default: h = (r - g) / d + 4;
    }
    h /= 6;
  }
  return { h: Math.round(h * 360), s: Math.round(s * 100), l: Math.round(l * 100) };
}
function luminance({ r, g, b }) {
  const a = [r, g, b].map((v) => { v /= 255; return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); });
  return 0.2126 * a[0] + 0.7152 * a[1] + 0.0722 * a[2];
}
function contrastRatio(l1, l2) { const [hi, lo] = l1 > l2 ? [l1, l2] : [l2, l1]; return (hi + 0.05) / (lo + 0.05); }
function cssColorVar(group, name) {
  return `--color-${group}-${name.replace(/^blue-/, "").replace(/[^a-z0-9]/gi, "-").toLowerCase()}`;
}
function typeVar(name) { return `--text-${name.toLowerCase().replace(/\s+/g, "-")}`; }

// ═══════════════════════════════════════════════════════════════
// COPY
// ═══════════════════════════════════════════════════════════════
function useCopy() {
  const [copied, setCopied] = useState(null);
  const timer = useRef(null);
  const copy = useCallback((value, id) => {
    const done = () => { setCopied(id); clearTimeout(timer.current); timer.current = setTimeout(() => setCopied(null), 1400); };
    if (navigator.clipboard?.writeText) navigator.clipboard.writeText(value).then(done).catch(() => { fallbackCopy(value); done(); });
    else { fallbackCopy(value); done(); }
  }, []);
  return { copied, copy };
}
function fallbackCopy(text) {
  const ta = document.createElement("textarea");
  ta.value = text; ta.style.position = "fixed"; ta.style.opacity = "0";
  document.body.appendChild(ta); ta.select();
  try { document.execCommand("copy"); } catch (e) {}
  document.body.removeChild(ta);
}

