// ═══════════════════════════════════════════════════════════════
// SHARED UI
// ═══════════════════════════════════════════════════════════════
function CopyValue({ label, value, id, copied, onCopy, mono = true }) {
  const isCopied = copied === id;
  return (
    <button className="copyval" data-copied={isCopied} onClick={() => onCopy(value, id)} title={`Copy ${value}`}>
      {label && <span className="copyval-key">{label}</span>}
      <span className="copyval-val" style={{ fontFamily: mono ? "var(--mono)" : "inherit" }}>{value}</span>
      <span className="copyval-icon" aria-hidden>
        {isCopied
          ? <svg viewBox="0 0 16 16" width="13" height="13"><path d="M13.5 4.5L6 12L2.5 8.5" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round"/></svg>
          : <svg viewBox="0 0 16 16" width="13" height="13"><rect x="5" y="5" width="8" height="8" rx="1.5" fill="none" stroke="currentColor" strokeWidth="1.4"/><path d="M3 11V4a1 1 0 011-1h7" fill="none" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round"/></svg>}
      </span>
    </button>
  );
}

function SectionHead({ eyebrow, title, children }) {
  return (
    <div className="section-head">
      <h2 className="section-title">{title}</h2>
      {children && <p className="section-desc">{children}</p>}
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════
// COLOR
// ═══════════════════════════════════════════════════════════════
function Swatch({ group, token, copied, onCopy }) {
  const isLight = luminance(hexToRgb(token.hex)) > 0.55;
  const hex = `#${token.hex.toUpperCase()}`;
  const id = `swatch-${group}-${token.name}`;
  const isCopied = copied === id;
  const fg = isLight ? "#010812" : "#FFFFFF";
  const fgDim = isLight ? "rgba(1,8,18,.55)" : "rgba(255,255,255,.65)";

  return (
    <div
      className="swatch"
      style={{ background: hex, boxShadow: isLight ? "inset 0 0 0 1px var(--line)" : "none" }}
    >
      <div className="swatch-hover">
        <button className="swatch-copy" onClick={() => onCopy(hex, id)} title={`Copy ${hex}`}>
          {isCopied ? "Copied" : "Copy HEX"}
        </button>
      </div>
      <div className="swatch-meta">
        <span className="swatch-name" style={{ color: fg }}>{token.name}</span>
        <span className="swatch-hex" style={{ color: fgDim }}>{hex}</span>
      </div>
    </div>
  );
}

function ColorGroup({ group, data, copied, onCopy }) {
  return (
    <div className="swatch-grid">
      {data.tokens.map((t) => (
        <Swatch key={t.name} group={group} token={t} copied={copied} onCopy={onCopy} />
      ))}
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════
// TYPOGRAPHY
// ═══════════════════════════════════════════════════════════════
function TypeRow({ token, breakpoint, copied, onCopy, expanded, onToggle }) {
  const rowId = `type-${breakpoint}-${token.name}`;
  const lhPx = Math.round((token.size * token.lh) / 100);
  const previewSize = Math.min(token.size, 44); // cap so huge sizes stay in the row
  const varName = typeVar(token.name);
  const cssBlock = `${varName}: ${token.size}px/${(token.lh / 100).toFixed(2)} 'Alliance No.2';`;
  const specimen = token.upper ? "The Spectrum" : "The quick brown fox";

  return (
    <div className="row trow" data-open={expanded}>
      <button className="row-head trow-head" onClick={() => onToggle(rowId)}>
        <span className="trow-specimen" style={{
          fontSize: previewSize, lineHeight: 1, fontWeight: token.weight,
          textTransform: token.upper ? "uppercase" : "none",
          letterSpacing: token.upper ? "0.08em" : token.size > 40 ? "-0.02em" : "-0.01em",
        }}>{specimen}</span>
        <span className="trow-meta">
          <span className="trow-name">{token.name}</span>
          <span className="trow-spec">{token.size} / {token.lh}</span>
        </span>
        <span className="row-chevron" aria-hidden><svg viewBox="0 0 12 12" width="12" height="12"><path d="M3 4.5L6 7.5L9 4.5" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"/></svg></span>
      </button>
      {expanded && (
        <div className="row-detail trow-detail">
          <div className="detail-values">
            <CopyValue label="Size" value={`${token.size}px`} id={`${rowId}-size`} copied={copied} onCopy={onCopy} />
            <CopyValue label="Line" value={`${lhPx}px (${token.lh}%)`} id={`${rowId}-lh`} copied={copied} onCopy={onCopy} />
            <CopyValue label="Weight" value={String(token.weight)} id={`${rowId}-w`} copied={copied} onCopy={onCopy} />
            <CopyValue label="Family" value="Alliance No.2" id={`${rowId}-fam`} copied={copied} onCopy={onCopy} mono={false} />
          </div>
          <div className="detail-values">
            <CopyValue label="CSS" value={cssBlock} id={`${rowId}-css`} copied={copied} onCopy={onCopy} />
            <CopyValue label="Var" value={`var(${varName})`} id={`${rowId}-var`} copied={copied} onCopy={onCopy} />
          </div>
        </div>
      )}
    </div>
  );
}

function TypeScale({ breakpoint, copied, onCopy, expandedRow, onToggleRow }) {
  return (
    <div className="rows">
      {TYPE_SCALE[breakpoint].map((t) => (
        <TypeRow key={t.name} token={t} breakpoint={breakpoint} copied={copied} onCopy={onCopy}
          expanded={expandedRow === `type-${breakpoint}-${t.name}`} onToggle={onToggleRow} />
      ))}
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════
// PLACEHOLDER (structure parity with the full Figma system)
// ═══════════════════════════════════════════════════════════════
function Placeholder({ note }) {
  return (
    <div className="placeholder">
      <div className="placeholder-grid">{Array.from({ length: 6 }).map((_, i) => <span key={i} />)}</div>
      <p>{note}</p>
    </div>
  );
}

